1	package clinical
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"reflect"
8		"testing"
9		"time"
10	)
11	
12	// TestRevokeSaveFailureKeepsStateAndAllowsRetry 覆盖“内部使用者提交的撤回本身
13	// 完全合法（身份有权、对象存在且属于该患者、授权尚未撤回），却因本地保存失败
14	// 而未能完成”的授权撤回场景。
15	//
16	// 前置数据：患者档案全程未停用；同一次就诊下有两条已生效诊断；同一接收方持有
17	// 两条当前有效的授权——准备撤回的目标授权整类覆盖这次就诊的全部诊断，另一条
18	// 限定授权只明确选出其中一条；接收方原本能读到两条诊断（每条只出现一次）；
19	// 另有一份绑定目标授权、固化这两条记录创建时版本的待回执交换。撤回失败尝试与
20	// 后续成功提交都落在两条授权的有效期内，因此访问变化只能来自撤回结果本身。
21	//
22	// 本地保存失败时：撤回必须以普通保存错误返回，不能报告成功，也不能伪装成身份
23	// 无权、对象不存在或参数不合法；目标授权在内部查询中仍未撤回，原范围、有效期
24	// 与另一条限定授权保持不变；既有审计的内容与顺序原样保留，不新增撤回事件；
25	// 接收方仍能读到原来的两条诊断（标识、当前版本、完整内容与排列顺序不变），
26	// 仍能取得原交换包及其摘要。
27	//
28	// 保存条件恢复后：同一目标授权可正常撤回，撤回时间属于这次成功操作，只新增
29	// 一条指向目标授权、记录实际操作身份与时间的撤回审计；接收方随后只能读到
30	// 限定授权明确允许的那一条诊断，另一条诊断的标识与内容都不再出现；即使剩余
31	// 授权允许读取包内一部分记录，绑定授权已撤回的原交换取包仍返回 ErrAccessDenied
32	// 且不携带包内容或摘要；内部使用者仍能查看原交换，固化内容、摘要与待回执状态
33	// 不变——撤回本身不登记回执、不改写诊断历史。
34	func TestRevokeSaveFailureKeepsStateAndAllowsRetry(t *testing.T) {
35		dir := t.TempDir()
36		clk := &fakeClock{t: time.Date(2026, 6, 1, 9, 0, 0, 0, time.UTC)}
37		open := func() *Store {
38			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
39			if err != nil {
40				t.Fatalf("open: %v", err)
41			}
42			return s
43		}
44	
45		s := open()
46		p, err := s.RegisterPatient(doc, "撤回保存失败患者")
47		if err != nil {
48			t.Fatal(err)
49		}
50		e, err := s.AddEncounter(doc, p.ID, time.Time{})
51		if err != nil {
52			t.Fatal(err)
53		}
54		// 同一次就诊下两条已生效诊断（均为第 1 版）。
55		activate := func(content string) (ID, Version) {
56			t.Helper()
57			r, err := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, content)
58			if err != nil {
59				t.Fatal(err)
60			}
61			v, err := s.ActivateRecord(doc, r.ID)
62			if err != nil {
63				t.Fatal(err)
64			}
65			return r.ID, v
66		}
67		d1, d1v1 := activate("诊断一内容")
68		d2, d2v1 := activate("诊断二内容")
69	
70		// 两条授权的时间窗覆盖失败尝试与成功提交的全部时刻：访问变化不能由
71		// 未开始、到期造成。
72		start := clk.t.Add(-time.Hour)
73		end := clk.t.Add(48 * time.Hour)
74		// 目标授权：整类覆盖这次就诊的全部诊断（d1 与 d2）。
75		target, err := s.Grant(doc, p.ID, rcv.ID,
76			[]Scope{{EncounterID: e.ID, Category: Diagnosis}}, start, end)
77		if err != nil {
78			t.Fatal(err)
79		}
80		// 另一条限定授权：只明确选出 d1。
81		limited, err := s.GrantSelective(doc, p.ID, rcv.ID, nil,
82			[]RecordSelection{sel(e.ID, Diagnosis, d1)}, start, end)
83		if err != nil {
84			t.Fatal(err)
85		}
86	
87		// 一份绑定目标授权、包含两条记录创建时版本（均为 v1）的待回执交换。
88		exch, err := s.CreateExchange(doc, p.ID, rcv.ID, target.ID, []ID{d1, d2}, "req-revoke-save-failure")
89		if err != nil {
90			t.Fatal(err)
91		}
92		if exch.Status != ExchangePending || exch.Receipt != nil {
93			t.Fatalf("baseline exchange should be pending without receipt: %+v", exch)
94		}
95	
96		// ---- 提交前的正式基线 ----
97		authsBefore, err := s.ListAuthorizations(doc, p.ID, "")
98		if err != nil {
99			t.Fatal(err)
100		}
101		if len(authsBefore) != 2 {
102			t.Fatalf("baseline authorizations = %+v, want 2", authsBefore)
103		}
104		targetBefore, err := s.GetAuthorization(doc, p.ID, target.ID)
105		if err != nil {
106			t.Fatal(err)
107		}
108		limitedBefore, err := s.GetAuthorization(doc, p.ID, limited.ID)
109		if err != nil {
110			t.Fatal(err)
111		}
112		auditBefore, err := s.AuditEvents(doc, p.ID)
113		if err != nil {
114			t.Fatal(err)
115		}
116		revokesBefore := auditActions(auditBefore)[ActionRevoked]
117		chartBefore, err := s.Chart(doc, p.ID)
118		if err != nil {
119			t.Fatal(err)
120		}
121		// 接收方原本能读到两条诊断，每条只出现一次并按标识稳定排序。
122		readBefore, err := s.Read(rcv, p.ID, e.ID, Diagnosis)
123		if err != nil {
124			t.Fatal(err)
125		}
126		if len(readBefore.Records) != 2 {
127			t.Fatalf("baseline read = %+v, want 2 diagnoses", readBefore)
128		}
129		baselineByID := map[ID]EffectiveRecord{}
130		for _, rec := range readBefore.Records {
131			if _, dup := baselineByID[rec.RecordID]; dup {
132				t.Fatalf("baseline read lists a record twice: %+v", readBefore.Records)
133			}
134			baselineByID[rec.RecordID] = rec
135		}
136		if got := baselineByID[d1]; got.VersionID != d1v1.ID || got.Version != 1 || got.Content != "诊断一内容" {
137			t.Fatalf("baseline d1 wrong: %+v", got)
138		}
139		if got := baselineByID[d2]; got.VersionID != d2v1.ID || got.Version != 1 || got.Content != "诊断二内容" {
140			t.Fatalf("baseline d2 wrong: %+v", got)
141		}
142		if readBefore.Records[0].RecordID > readBefore.Records[1].RecordID {
143			t.Fatalf("baseline read not in stable order: %+v", readBefore.Records)
144		}
145		// 接收方原本能取得原交换包及其摘要。
146		deliveryBefore, err := s.FetchPackage(rcv, exch.ID)
147		if err != nil {
148			t.Fatalf("baseline fetch package: %v", err)
149		}
150		if deliveryBefore.Digest != exch.Digest || len(deliveryBefore.Package.Records) != 2 {
151			t.Fatalf("baseline delivery wrong: %+v", deliveryBefore)
152		}
153		exchangeBefore, err := s.GetExchange(doc, p.ID, exch.ID)
154		if err != nil {
155			t.Fatal(err)
156		}
157	
158		// checkIntact 断言：失败尝试之后（以及重开之后），授权撤回状态、审计、
159		// 接收方可见内容与原交换包都与提交前逐项一致——撤回状态、撤回审计与
160		// 接收方可见内容必须对应同一次成功操作，失败尝试不能提前阻断访问，
161		// 也不能留下看起来已经成功的撤回事件。
162		checkIntact := func(label string, st *Store) {
163			t.Helper()
164	
165			// 目标授权仍未撤回：原整类范围、时间窗保持原样。
166			gotTarget, err := st.GetAuthorization(doc, p.ID, target.ID)
167			if err != nil {
168				t.Fatalf("%s: get target authorization: %v", label, err)
169			}
170			if !reflect.DeepEqual(gotTarget, targetBefore) {
171				t.Fatalf("%s: target authorization changed:\nbefore: %+v\nafter:  %+v",
172					label, targetBefore, gotTarget)
173			}
174			if gotTarget.RevokedAt != nil {
175				t.Fatalf("%s: target authorization must not be revoked: %+v", label, gotTarget)
176			}
177			if !gotTarget.ActiveAt(clk.t) {
178				t.Fatalf("%s: target authorization must stay active at %v: %+v", label, clk.t, gotTarget)
179			}
180			// 另一条限定授权同样保持不变且仍在有效期内。
181			gotLimited, err := st.GetAuthorization(doc, p.ID, limited.ID)
182			if err != nil {
183				t.Fatalf("%s: get limited authorization: %v", label, err)
184			}
185			if !reflect.DeepEqual(gotLimited, limitedBefore) {
186				t.Fatalf("%s: limited authorization changed:\nbefore: %+v\nafter:  %+v",
187					label, limitedBefore, gotLimited)
188			}
189			if !gotLimited.ActiveAt(clk.t) {
190				t.Fatalf("%s: limited authorization must stay active at %v: %+v", label, clk.t, gotLimited)
191			}
192			if auths, err := st.ListAuthorizations(doc, p.ID, ""); err != nil ||
193				!reflect.DeepEqual(auths, authsBefore) {
194				t.Fatalf("%s: authorization list changed:\nbefore: %+v\nafter:  %+v err=%v",
195					label, authsBefore, auths, err)
196			}
197	
198			// 既有审计的内容与顺序原样保留，不新增撤回事件。
199			audit, err := st.AuditEvents(doc, p.ID)
200			if err != nil {
201				t.Fatalf("%s: audit: %v", label, err)
202			}
203			if !reflect.DeepEqual(audit, auditBefore) {
204				t.Fatalf("%s: audit events changed:\nbefore: %+v\nafter:  %+v", label, auditBefore, audit)
205			}
206			if got := auditActions(audit)[ActionRevoked]; got != revokesBefore {
207				t.Fatalf("%s: authorization_revoked events = %d, want %d", label, got, revokesBefore)
208			}
209	
210			// 患者档案未停用。
211			patient, err := st.GetPatient(doc, p.ID)
212			if err != nil {
213				t.Fatalf("%s: get patient: %v", label, err)
214			}
215			if patient.Deactivated {
216				t.Fatalf("%s: patient must not be deactivated", label)
217			}
218	
219			// 接收方仍能读到原来的两条诊断：标识、当前版本、完整内容与顺序不变。
220			res, err := st.Read(rcv, p.ID, e.ID, Diagnosis)
221			if err != nil {
222				t.Fatalf("%s: receiver read: %v", label, err)
223			}
224			if !reflect.DeepEqual(res, readBefore) {
225				t.Fatalf("%s: receiver read changed:\nbefore: %+v\nafter:  %+v", label, readBefore, res)
226			}
227	
228			// 接收方仍能取得原交换包及其摘要。
229			delivery, err := st.FetchPackage(rcv, exch.ID)
230			if err != nil {
231				t.Fatalf("%s: receiver fetch package: %v", label, err)
232			}
233			if !reflect.DeepEqual(delivery, deliveryBefore) {
234				t.Fatalf("%s: package delivery changed:\nbefore: %+v\nafter:  %+v",
235					label, deliveryBefore, delivery)
236			}
237	
238			// 内部使用者看到的原交换固化内容、摘要与待回执状态不变。
239			gotExch, err := st.GetExchange(doc, p.ID, exch.ID)
240			if err != nil {
241				t.Fatalf("%s: internal get exchange: %v", label, err)
242			}
243			assertExchangeMatches(t, gotExch, exchangeBefore, label+": exchange")
244		}
245	
246		// 制造本地保存失败：数据文件原位置被同名目录占据，原子改名必然失败，
247		// 与身份、对象存在性或参数合法性无关。原数据文件先挪到旁边，事后还原。
248		clk.t = clk.t.Add(time.Hour)
249		dataPath := filepath.Join(dir, dataName)
250		backupPath := dataPath + ".saved"
251		if err := os.Rename(dataPath, backupPath); err != nil {
252			t.Fatalf("backup data file: %v", err)
253		}
254		if err := os.Mkdir(dataPath, 0o755); err != nil {
255			t.Fatalf("block data path: %v", err)
256		}
257	
258		// 撤回本身完全合法，仅本地保存失败：必须返回保存错误，不能报告成功，
259		// 也不能误报为身份无权、对象不存在、跨患者、档案停用或参数不合法。
260		if err := s.Revoke(doc, p.ID, target.ID); err == nil {
261			t.Fatal("revoke must fail when local save fails")
262		} else if errors.Is(err, ErrAccessDenied) || errors.Is(err, ErrNotFound) ||
263			errors.Is(err, ErrMismatchedPatient) || errors.Is(err, ErrInvalidArgument) ||
264			errors.Is(err, ErrDeactivated) || errors.Is(err, ErrConflict) {
265			t.Fatalf("save failure surfaced as a business error: %v", err)
266		}
267		// 失败不能留下半截写入的临时文件。
268		if _, statErr := os.Stat(dataPath + ".tmp"); !os.IsNotExist(statErr) {
269			t.Fatalf("failed save left a temp file: %v", statErr)
270		}
271	
272		// 失败后：撤回状态、审计、接收方可见内容与交换包全部维持提交前状态。
273		checkIntact("after failed save", s)
274	
275		// 关闭后从原数据位置重新打开：先恢复保存条件（还原原数据文件）。
276		if err := s.Close(); err != nil {
277			t.Fatal(err)
278		}
279		if err := os.Remove(dataPath); err != nil {
280			t.Fatalf("unblock data path: %v", err)
281		}
282		if err := os.Rename(backupPath, dataPath); err != nil {
283			t.Fatalf("restore data file: %v", err)
284		}
285	
286		s2 := open()
287		t.Cleanup(func() { _ = s2.Close() })
288		// 重开后仍是提交前的正式数据：失败的撤回不留任何痕迹。
289		checkIntact("after reopen", s2)
290	
291		// 保存条件恢复后：同一目标授权正常撤回。时刻仍在两条授权的有效期内、
292		// 患者仍未停用，因此随后的访问变化只能来自这次成功撤回。
293		clk.t = clk.t.Add(time.Hour)
294		if err := s2.Revoke(doc, p.ID, target.ID); err != nil {
295			t.Fatalf("retry after save recovered: %v", err)
296		}
297	
298		// 目标授权已撤回，撤回时间属于这次成功操作；范围与有效期原样保留。
299		gotTarget, err := s2.GetAuthorization(doc, p.ID, target.ID)
300		if err != nil {
301			t.Fatal(err)
302		}
303		if gotTarget.RevokedAt == nil || !gotTarget.RevokedAt.Equal(clk.t) {
304			t.Fatalf("target revocation time = %v, want %v", gotTarget.RevokedAt, clk.t)
305		}
306		if !reflect.DeepEqual(gotTarget.Scopes, targetBefore.Scopes) ||
307			!reflect.DeepEqual(gotTarget.Selections, targetBefore.Selections) ||
308			!gotTarget.StartsAt.Equal(targetBefore.StartsAt) ||
309			!gotTarget.ExpiresAt.Equal(targetBefore.ExpiresAt) {
310			t.Fatalf("revoked authorization scope/window changed:\nbefore: %+v\nafter:  %+v",
311				targetBefore, gotTarget)
312		}
313		// 另一条限定授权保持原样且仍在有效期内。
314		gotLimited, err := s2.GetAuthorization(doc, p.ID, limited.ID)
315		if err != nil {
316			t.Fatal(err)
317		}
318		if !reflect.DeepEqual(gotLimited, limitedBefore) {
319			t.Fatalf("limited authorization changed after revoke:\nbefore: %+v\nafter:  %+v",
320				limitedBefore, gotLimited)
321		}
322	
323		// 审计相对提交前基线只新增一条撤回事件，指向目标授权并记录实际操作
324		// 身份与时间；既有事件的内容与顺序原样保留。
325		audit, err := s2.AuditEvents(doc, p.ID)
326		if err != nil {
327			t.Fatal(err)
328		}
329		if len(audit) != len(auditBefore)+1 || !reflect.DeepEqual(audit[:len(auditBefore)], auditBefore) {
330			t.Fatalf("audit after successful revoke:\nbefore: %+v\nafter:  %+v", auditBefore, audit)
331		}
332		last := audit[len(audit)-1]
333		if last.Action != ActionRevoked || last.ObjectType != "authorization" ||
334			last.ObjectID != target.ID || last.ActorID != doc.ID ||
335			last.PatientID != p.ID || !last.OccurredAt.Equal(clk.t) {
336			t.Fatalf("unexpected new audit event: %+v", last)
337		}
338		if got := auditActions(audit)[ActionRevoked]; got != revokesBefore+1 {
339			t.Fatalf("authorization_revoked events = %d, want %d", got, revokesBefore+1)
340		}
341	
342		// 接收方随后只能读到另一条限定授权明确允许的 d1；d2 的标识与内容都
343		// 不再出现在读取结果中。
344		res, err := s2.Read(rcv, p.ID, e.ID, Diagnosis)
345		if err != nil {
346			t.Fatalf("receiver read after successful revoke: %v", err)
347		}
348		if len(res.Records) != 1 {
349			t.Fatalf("read after revoke = %+v, want only the selected diagnosis", res.Records)
350		}
351		only := res.Records[0]
352		if only.RecordID != d1 || only.VersionID != d1v1.ID ||
353			only.Version != 1 || only.Content != "诊断一内容" {
354			t.Fatalf("remaining visible diagnosis wrong: %+v", only)
355		}
356		for _, rec := range res.Records {
357			if rec.RecordID == d2 {
358				t.Fatalf("d2 record id must disappear after revoke: %+v", rec)
359			}
360			if rec.Content == "诊断二内容" {
361				t.Fatalf("d2 content must disappear after revoke: %+v", rec)
362			}
363		}
364	
365		// 即使剩余的限定授权允许读取包内的一部分记录（d1），原交换绑定的目标
366		// 授权已撤回：取包必须 ErrAccessDenied，响应不携带包内容或摘要。
367		if delivery, err := s2.FetchPackage(rcv, exch.ID); !errors.Is(err, ErrAccessDenied) {
368			t.Fatalf("fetch after bound auth revoked: delivery=%+v err=%v, want ErrAccessDenied",
369				delivery, err)
370		} else if delivery.Digest != "" || len(delivery.Package.Records) != 0 ||
371			delivery.ExchangeID != "" || delivery.Status != "" {
372			t.Fatalf("denied fetch must carry no package content or digest: %+v", delivery)
373		}
374	
375		// 内部使用者仍能查看原交换：固化内容（两条记录的创建时 v1）、摘要与
376		// 待回执状态保持不变；撤回本身不登记回执。
377		gotExch, err := s2.GetExchange(doc, p.ID, exch.ID)
378		if err != nil {
379			t.Fatalf("internal get exchange after revoke: %v", err)
380		}
381		assertExchangeMatches(t, gotExch, exchangeBefore, "exchange after revoke")
382		if gotExch.Status != ExchangePending || gotExch.Receipt != nil {
383			t.Fatalf("revoke must not register a receipt or change status: %+v", gotExch)
384		}
385		if len(gotExch.Package.Records) != 2 || gotExch.Digest != exchangeBefore.Digest {
386			t.Fatalf("frozen package/digest changed after revoke: %+v", gotExch)
387		}
388		pkgByID := recordsByID(gotExch.Package.Records)
389		if pr := pkgByID[d1]; pr.VersionID != d1v1.ID || pr.Content != "诊断一内容" {
390			t.Fatalf("frozen d1 wrong: %+v", pr)
391		}
392		if pr := pkgByID[d2]; pr.VersionID != d2v1.ID || pr.Content != "诊断二内容" {
393			t.Fatalf("frozen d2 wrong: %+v", pr)
394		}
395	
396		// 撤回不改写诊断历史：两条诊断的版本链与当前版本与提交前完全一致。
397		chart, err := s2.Chart(doc, p.ID)
398		if err != nil {
399			t.Fatal(err)
400		}
401		if !reflect.DeepEqual(chart.Records, chartBefore.Records) {
402			t.Fatalf("diagnosis history changed by revoke:\nbefore: %+v\nafter:  %+v",
403				chartBefore.Records, chart.Records)
404		}
405	
406		// 重复撤回幂等：不产生额外变化，也不新增审计事件（沿用既有撤回规则）。
407		if err := s2.Revoke(doc, p.ID, gotTarget.ID); err != nil {
408			t.Fatalf("repeat revoke must stay successful: %v", err)
409		}
410		again, err := s2.GetAuthorization(doc, p.ID, target.ID)
411		if err != nil {
412			t.Fatal(err)
413		}
414		if again.RevokedAt == nil || !again.RevokedAt.Equal(clk.t) {
415			t.Fatalf("repeat revoke altered revocation time: %v", again.RevokedAt)
416		}
417		if evs, err := s2.AuditEvents(doc, p.ID); err != nil || len(evs) != len(audit) {
418			t.Fatalf("repeat revoke added audit events: before=%d after=%d err=%v",
419				len(audit), len(evs), err)
420		}
421	
422		// 关闭后从同一数据位置重新打开：成功撤回与其唯一审计完整保留，失败尝试
423		// 不能作为额外的撤回状态或事件出现。
424		if err := s2.Close(); err != nil {
425			t.Fatal(err)
426		}
427		s3 := open()
428		t.Cleanup(func() { _ = s3.Close() })
429	
430		reloaded, err := s3.GetAuthorization(doc, p.ID, target.ID)
431		if err != nil {
432			t.Fatalf("get revoked authorization after reopen: %v", err)
433		}
434		if reloaded.RevokedAt == nil || !reloaded.RevokedAt.Equal(clk.t) {
435			t.Fatalf("revocation not persisted after reopen: %+v", reloaded)
436		}
437		if delivery, err := s3.FetchPackage(rcv, exch.ID); !errors.Is(err, ErrAccessDenied) ||
438			delivery.Digest != "" || len(delivery.Package.Records) != 0 {
439			t.Fatalf("fetch after reopen: delivery=%+v err=%v, want ErrAccessDenied without content",
440				delivery, err)
441		}
442		reloadedExch, err := s3.GetExchange(doc, p.ID, exch.ID)
443		if err != nil {
444			t.Fatalf("get exchange after reopen: %v", err)
445		}
446		assertExchangeMatches(t, reloadedExch, exchangeBefore, "exchange after reopen")
447	
448		var revokeIDs []ID
449		for _, ev := range mustAudit(t, s3, p.ID) {
450			if ev.Action == ActionRevoked {
451				revokeIDs = append(revokeIDs, ev.ObjectID)
452			}
453		}
454		if !reflect.DeepEqual(revokeIDs, []ID{target.ID}) {
455			t.Fatalf("revocation events after reopen = %v, want only [%q]", revokeIDs, target.ID)
456		}
457	}
458

