package clinical

import (
	"os"
	"path/filepath"
	"testing"
	"time"
)

// 验证：已撤回的授权在保存条件不可用时重复撤回仍成功，且不改写已保存内容。
func TestRepeatRevokeSucceedsWhenSaveUnavailable(t *testing.T) {
	dir := t.TempDir()
	clk := &fakeClock{t: time.Date(2026, 6, 1, 9, 0, 0, 0, time.UTC)}
	s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
	if err != nil {
		t.Fatal(err)
	}
	defer s.Close()

	p, _ := s.RegisterPatient(doc, "重复撤回患者")
	e, _ := s.AddEncounter(doc, p.ID, time.Time{})
	a, _ := s.Grant(doc, p.ID, rcv.ID,
		[]Scope{{EncounterID: e.ID, Category: Diagnosis}},
		clk.t.Add(-time.Hour), clk.t.Add(24*time.Hour))

	revokeTime := clk.t
	if err := s.Revoke(doc, p.ID, a.ID); err != nil {
		t.Fatal(err)
	}
	auditBefore, _ := s.AuditEvents(doc, p.ID)

	// 让保存不可用：数据文件位置被同名目录占据。
	dataPath := filepath.Join(dir, dataName)
	backup := dataPath + ".saved"
	if err := os.Rename(dataPath, backup); err != nil {
		t.Fatal(err)
	}
	if err := os.Mkdir(dataPath, 0o755); err != nil {
		t.Fatal(err)
	}
	defer func() {
		os.Remove(dataPath)
		os.Rename(backup, dataPath)
	}()

	// 另一名有权的内部使用者、更晚时刻重复确认：必须成功。
	clk.t = clk.t.Add(2 * time.Hour)
	doc2 := InternalActor("doctor-2")
	if err := s.Revoke(doc2, p.ID, a.ID); err != nil {
		t.Fatalf("repeat revoke with save unavailable must succeed: %v", err)
	}

	// 撤回时间保持首次成功撤回的时间，审计不新增。
	got, _ := s.GetAuthorization(doc, p.ID, a.ID)
	if got.RevokedAt == nil || !got.RevokedAt.Equal(revokeTime) {
		t.Fatalf("revocation time changed: %v, want %v", got.RevokedAt, revokeTime)
	}
	auditAfter, _ := s.AuditEvents(doc, p.ID)
	if len(auditAfter) != len(auditBefore) {
		t.Fatalf("repeat revoke added audit events: %d -> %d", len(auditBefore), len(auditAfter))
	}
}
EOF
